import{_ as i,o,c as e,ah as n}from"./chunks/framework.BMM80GXQ.js";const a="/assets/2.0/images/notifications/notification-panel.png",h=JSON.parse('{"title":"Notifications","description":"","frontmatter":{},"headers":[],"relativePath":"2.0/notifications/index.md","filePath":"2.0/notifications/index.md","lastUpdated":1775051911000}'),s={name:"2.0/notifications/index.md"};function r(l,t,c,p,u,d){return o(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h1><p>Notifications in <a href="https://unopim.com/" target="_blank" rel="noreferrer">UnoPim</a> provide a real-time, in-app alerting system that keeps administrators informed about important events and background processes. Introduced in <strong>v0.2.0</strong>, the notification system works alongside optional email notifications to ensure you never miss critical updates.</p><p>Whether it&#39;s the completion of a bulk import, a failed export job, or a product change, notifications help you stay on top of everything happening in your PIM without needing to constantly check each section manually.</p><h3 id="accessing-notifications" tabindex="-1">Accessing Notifications <a class="header-anchor" href="#accessing-notifications" aria-label="Permalink to &quot;Accessing Notifications&quot;">​</a></h3><p>To access your notifications, click the <strong>Bell Icon</strong> in the top navigation bar of the Admin panel. This opens the notification panel where you can view all recent alerts.</p><p><img src="'+a+'" alt="Notification Panel"></p><h3 id="types-of-notifications" tabindex="-1">Types of Notifications <a class="header-anchor" href="#types-of-notifications" aria-label="Permalink to &quot;Types of Notifications&quot;">​</a></h3><p>UnoPim sends notifications for various system events. Below are the main categories:</p><p><strong>1) Import/Export Job Status Updates</strong></p><p>Whenever you run a bulk import or export job, UnoPim automatically sends a notification when the job is completed, failed, or requires attention. This allows you to monitor long-running data transfer operations without staying on the job tracker page.</p><ul><li><strong>Completed</strong> — The import or export job finished successfully.</li><li><strong>Failed</strong> — The job encountered errors and could not complete.</li><li><strong>Completed with Errors</strong> — The job finished but some records were skipped due to validation issues.</li></ul><p><strong>2) Product Changes</strong></p><p>Notifications can alert you when significant product data modifications occur, such as bulk updates or changes made through the API. This is useful when multiple team members are working on the product catalog simultaneously.</p><p><strong>3) System Notifications</strong></p><p>General system-level alerts, such as scheduled maintenance reminders or important configuration changes, are also delivered through the notification panel.</p><h3 id="notification-panel-features" tabindex="-1">Notification Panel Features <a class="header-anchor" href="#notification-panel-features" aria-label="Permalink to &quot;Notification Panel Features&quot;">​</a></h3><p>The notification panel provides several options to help you manage your alerts efficiently:</p><p><strong>1) View All Notifications</strong></p><p>Click the <strong>Bell Icon</strong> to see a list of all your recent notifications. Each notification displays a brief summary, the timestamp, and the current read/unread status.</p><p><strong>2) Mark as Read/Unread</strong></p><p>You can mark individual notifications as read or unread. Unread notifications are highlighted so you can quickly identify new alerts. Click on a notification to mark it as read automatically.</p><p><strong>3) Clear Notifications</strong></p><p>To keep your notification panel clean, you can clear notifications that are no longer needed. This removes them from the panel so you can focus on the most recent and relevant alerts.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Regularly clearing old notifications helps you stay organized and quickly spot new important alerts.</p></div><h3 id="email-notifications" tabindex="-1">Email Notifications <a class="header-anchor" href="#email-notifications" aria-label="Permalink to &quot;Email Notifications&quot;">​</a></h3><p>In addition to in-app notifications, UnoPim supports email notifications for critical events. When enabled, the system sends an email to the administrator&#39;s registered email address alongside the in-app notification.</p><p><strong>How Email Notifications Work</strong></p><p>Email notifications are sent automatically for key events such as import/export job completions and failures. This ensures that even if you are not actively logged into the Admin panel, you still receive timely updates.</p><p><strong>Configuration</strong></p><p>To configure email notifications, ensure your mail settings are properly set up under <strong>Configuration &gt;&gt; Email</strong>. UnoPim uses the configured mail driver (SMTP, Mailgun, etc.) to deliver notification emails.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Make sure your mail configuration is tested and working before relying on email notifications. You can verify this by sending a test email from the configuration panel.</p></div><p>By using both in-app and email notifications together, you can ensure complete visibility into all important events happening within your UnoPim instance.</p>',32)])])}const m=i(s,[["render",r]]);export{h as __pageData,m as default};
